"""
Leakage-Free Fold Preprocessing & Generation Helpers.
Guarantees all scalers, imputers, and anomaly thresholds are strictly fitted
on training fold data, then applied immutably across validation, test, and synthetic data.
"""

import numpy as np
import pandas as pd
from typing import Tuple, List, Dict, Optional
from sklearn.preprocessing import StandardScaler, MinMaxScaler
from sklearn.impute import SimpleImputer

from preprocessing import clean_anomalies_shared, engineer_features_shared


# Base independent features generated by WGAN-GP (excludes derived neu_lym, patient_id, label)
BASE_GEN_FEATURES = [
    "gender", "age", "neu", "lym", "hb", "hct", "rdw", "plt",
    "alb", "alt", "tb", "cr", "tg", "chol", "hdl", "ldl", "lpa",
    "cea", "ca125", "ca199", "ca724"
]

# Skewed features to log1p-transform before scaling for GAN stability
DEFAULT_LOG_COLS = ["cea", "ca199", "ca125", "ca724", "lpa", "alt", "tb", "tg"]


class FoldFitDataCleaner:
    """
    Stateful anomaly cleaner fitted strictly on training data.
    Prevents leakage by locking the 99th percentile RDW cap on training fold rows.
    """

    def __init__(self):
        self.rdw_cap: Optional[float] = None
        self.is_fitted: bool = False

    def fit(self, df: pd.DataFrame) -> "FoldFitDataCleaner":
        rdw_valid = df[df["rdw"] <= 40.0]["rdw"]
        self.rdw_cap = float(rdw_valid.quantile(0.99)) if len(rdw_valid) > 0 else 18.5
        self.is_fitted = True
        return self

    def transform(self, df: pd.DataFrame) -> pd.DataFrame:
        if not self.is_fitted:
            raise RuntimeError("Cleaner must be fit before transform.")
        df_clean = df.copy()

        # Fix Hemoglobin typographical decimal error (>300 g/L is non-viable)
        hb_mask = df_clean["hb"] > 300.0
        if hb_mask.sum() > 0:
            df_clean.loc[hb_mask, "hb"] = df_clean.loc[hb_mask, "hb"] / 10.0

        # Fix Albumin typographical decimal error (>100 g/L is non-viable)
        alb_mask = df_clean["alb"] > 100.0
        if alb_mask.sum() > 0:
            df_clean.loc[alb_mask, "alb"] = df_clean.loc[alb_mask, "alb"] / 10.0

        # Fix RDW outliers using the learned training cap
        rdw_mask = df_clean["rdw"] > 40.0
        if rdw_mask.sum() > 0:
            df_clean.loc[rdw_mask, "rdw"] = self.rdw_cap

        return df_clean


class FoldPreprocessor:
    """
    Manages complete, leak-free preprocessing per fold:
    1. Cleaning anomalies (stateful via FoldFitDataCleaner)
    2. Imputation (SimpleImputer)
    3. Log-transforms + scaling for WGAN-GP
    4. Post-processing synthetic samples back to valid clinical base space
    5. Recomputing derived & engineered features
    """

    def __init__(
        self,
        scaler_type: str = "standard",
        log_cols: Optional[List[str]] = None,
        base_features: Optional[List[str]] = None,
    ):
        self.scaler_type = scaler_type
        self.log_cols = log_cols or DEFAULT_LOG_COLS
        self.base_features = base_features or BASE_GEN_FEATURES

        self.cleaner = FoldFitDataCleaner()
        self.imputer = SimpleImputer(strategy="median")
        self.scaler = StandardScaler() if scaler_type == "standard" else MinMaxScaler(feature_range=(-1, 1))

        self.is_fitted = False

    def fit(self, train_df: pd.DataFrame) -> "FoldPreprocessor":
        # 1. Fit cleaner
        self.cleaner.fit(train_df)
        df_clean = self.cleaner.transform(train_df)

        # 2. Extract base features
        X_base = df_clean[self.base_features].copy()

        # 3. Fit imputer
        self.imputer.fit(X_base)
        X_imp = self.imputer.transform(X_base)
        X_df_imp = pd.DataFrame(X_imp, columns=self.base_features)

        # 4. Log1p transform skewed features before scaling
        for col in self.log_cols:
            if col in X_df_imp.columns:
                X_df_imp[col] = np.log1p(X_df_imp[col].clip(lower=0))

        # 5. Fit scaler
        self.scaler.fit(X_df_imp.values)
        self.is_fitted = True
        return self

    def transform_for_gan(self, df: pd.DataFrame) -> np.ndarray:
        """Transforms base features into scaled space for GAN training."""
        if not self.is_fitted:
            raise RuntimeError("Must fit FoldPreprocessor before transforming.")
        df_clean = self.cleaner.transform(df)
        X_base = df_clean[self.base_features].copy()
        X_imp = self.imputer.transform(X_base)
        X_df_imp = pd.DataFrame(X_imp, columns=self.base_features)

        for col in self.log_cols:
            if col in X_df_imp.columns:
                X_df_imp[col] = np.log1p(X_df_imp[col].clip(lower=0))

        return self.scaler.transform(X_df_imp.values)

    def inverse_transform_synthetic(self, X_scaled: np.ndarray, y_labels: np.ndarray) -> pd.DataFrame:
        """
        Inverse-transforms generated scaled vectors, applies clinical post-processing,
        and recomputes all derived & engineered features.
        """
        if not self.is_fitted:
            raise RuntimeError("Must fit FoldPreprocessor before inverse transforming.")

        # 1. Inverse scaler
        X_inv = self.scaler.inverse_transform(X_scaled)
        df_syn = pd.DataFrame(X_inv, columns=self.base_features)

        # 2. Inverse log1p transforms
        for col in self.log_cols:
            if col in df_syn.columns:
                # expm1, clipping to prevent overflow
                df_syn[col] = np.expm1(df_syn[col].clip(lower=0, upper=15.0)).clip(lower=0.0)

        # 3. Clinical Bounds & Post-Processing (Reuse project definitions)
        # Binary gender: threshold at 0.5
        if "gender" in df_syn.columns:
            df_syn["gender"] = (df_syn["gender"] >= 0.5).astype(float)

        # Ordinal age: round and clip to integer range 2 - 9
        if "age" in df_syn.columns:
            df_syn["age"] = np.clip(np.round(df_syn["age"]), 2, 9).astype(float)

        # Biological counts and concentrations must be non-negative
        non_negative_cols = [c for c in self.base_features if c not in ["gender", "age"]]
        for col in non_negative_cols:
            df_syn[col] = np.maximum(df_syn[col], 0.0)

        # Hematocrit bounds: standard clinical range [0.10, 0.70]
        if "hct" in df_syn.columns:
            df_syn["hct"] = np.clip(df_syn["hct"], 0.10, 0.70)

        # Clean anomalies (apply learned RDW cap and typography checks)
        df_syn = self.cleaner.transform(df_syn)

        # 4. Recompute derived neu_lym
        df_syn["neu_lym"] = df_syn["neu"] / (df_syn["lym"] + 1e-5)

        # Assign class label
        df_syn["label"] = y_labels.astype(int)

        # 5. Recompute all engineered features via project's exact function
        df_syn_eng = engineer_features_shared(df_syn)

        return df_syn_eng

    def process_real_downstream(self, df: pd.DataFrame) -> pd.DataFrame:
        """Cleans and engineers features on real patient dataframe."""
        df_clean = self.cleaner.transform(df)
        df_eng = engineer_features_shared(df_clean)
        return df_eng
